function a = articulation(nmat);% function a = articulation(nmat);% returns the proportion of the time when at least one note% is sounding to the total duration of nmat% Music Therapy Toolboxif isempty(nmat)	a=0;	return;endon = onsetsec(nmat); on=on-on(1);db = dursec(nmat);off = on+db;td = on(end)+db(end);sumdur=0; x(1) = on(1); y(1) = off(1);n=1;for k = 2:nnotes(nmat)	if on(k)<off(k-1)		y(n)=off(k);	else		n=n+1;		x(n)=on(k); y(n)=off(k);	endendsumdur=sum(y-x);a = sumdur/td;